#define PIXFONT_MAX_RECTS 1024

void pixfont_draw(int x, int y, int scale, unsigned long rgb, const char *s)
{
	static int r[PIXFONT_MAX_RECTS * 4];
	const unsigned char *g;
	int n = 0, cx = x, row, col, run, bits;

	if (scale < 1)
		scale = 1;
	for (; *s; s++) {
		unsigned char c = (unsigned char)*s;

		if (c < 0x20 || c > 0x7E)
			c = '?';
		g = g_glyph[c - 0x20];
		for (row = 0; row < PIXFONT_H; row++) {
			bits = g[row];
			for (col = 0; col < PIXFONT_W && n < PIXFONT_MAX_RECTS; ) {
				if (!(bits & (1 << (PIXFONT_W - 1 - col)))) {
					col++;
					continue;
				}
				for (run = 0; col + run < PIXFONT_W &&
				     (bits & (1 << (PIXFONT_W - 1 - col - run)));
				     run++)
					;
				r[4 * n + 0] = cx + col * scale;
				r[4 * n + 1] = y + row * scale;
				r[4 * n + 2] = run * scale;
				r[4 * n + 3] = scale;
				n++;
				col += run;
			}
		}
		cx += PIXFONT_ADV * scale;
	}
	if (n) {
		overlay_color(rgb);
		overlay_fill_rects(r, n);
	}
}

int pixfont_width(const char *s, int scale)
{
	int n = (int)strlen(s);

	if (n <= 0 || scale < 1)
		return 0;
	return (n * PIXFONT_ADV - 1) * scale;
}
